  ],
  "claims": [
    {
      "claim": "All supplied L1 gold F records are at or above the 20% threshold (thalidomide 80-100%, clopenthixol 40-60%, proguanil up to 60%, ampicillin 30-50%, omapatrilat 21.9-31%, zilascorb 32-34%, PNU-96391 60%); no direct F record affirmatively supports F < 20%.",
      "card_ids": ["C21","C13","C02","C09","C15","C18","C16","C10","C19"]
    },
    {
      "claim": "The closest supplied solubility analog, buparvaquone, has very poor aqueous solubility (<300 ng/mL) and high lipophilicity, which is a negative absorption factor; however, poor solubility alone is not affirmative evidence of F < 20%, and the query is under a high-fat fed condition.",
      "card_ids": ["C52"]
    },
    {
      "claim": "L5 gut-wall/intestinal-metabolism records show high passive permeability and no net efflux for several molecules (loratadine ER 1.0, tryptanthrin ER 1.12, naringenin passive diffusion, diazepam high passive permeability), directionally supporting absorption, though not query-matched.",
      "card_ids": ["C70","C61","C63","C59"]
    },
    {
      "claim": "L6 hepatic-clearance records are mostly for unrelated molecules; the only structurally relevant records are for buparvaquone (a tert-butyl analog of the query's naphthoquinone core), showing rapid CYP2C9-mediated hydroxylation in human liver microsomes. This is directionally unfavorable if transferred, but the p-chlorophenyl vs tert-butyl difference and lack of query-matched clearance or F data limit applicability.",
      "card_ids": ["C77","C82"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "contradictory",
      "decision_effect": "no_change",
      "card_ids": ["C77","C82"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is present in the supplied records.",
    "No IV comparator or query-matched food-effect magnitude is supplied.",
    "L6 hepatic-clearance records are for other molecules; buparvaquone is the closest analog but differs at the cyclohexyl substituent (tert-butyl vs p-chlorophenyl).",
    "No query-specific solubility, permeability, efflux, or first-pass extraction data are supplied.",
    "The margin above the 20% threshold under the high-fat fed condition is uncertain."
  ],
  "decision_summary": "Prediction remains high: all direct L1 F records are at or above 20%, no affirmative low-F evidence is present, and the high-fat fed condition is favorable for absorption of this lipophilic, poorly soluble atovaquone-type naphthoquinone. L6 hepatic-clearance records are mostly unrelated; the buparvaquone analog shows rapid CYP2C9 metabolism but is not query-matched and does not establish F < 20%. Confidence remains moderate."
}

